#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# The cutover: the orchestrator moves from this laptop to Fly.io for good. Run it from the repo
# root, on main, once:  orchestrator/scripts/fly-cutover.sh
# What it sets up is described in fly.toml, .github/workflows/deploy.yml and the root README.md.
APP=oscar-bunny-factory
ORCH=orchestrator
ENV_FILE=.env   # read for the secrets; this wizard writes nothing to it

TOTAL_STAGES=7

banner "Bunny factory: move the orchestrator to Fly.io"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Stop the local orchestrator for good"
say "Runs in flight on the laptop must finish first: Fly starts from a copy of its factory.db."
[[ "$(git rev-parse --abbrev-ref HEAD)" == "main" ]] || warn "You're on $(git rev-parse --abbrev-ref HEAD), not main: the first deploy ships this checkout."
open_count() { sqlite3 "$ORCH/data/factory.db" "select count(*) from runs where status in ('requested','running')"; }
while true; do
  step "Stop the local orchestrator (npm run dev) and the Inngest dev server (npm run inngest)."
  pause "Both stopped?"
  n=$(open_count)
  [[ "$n" == "0" ]] && break
  warn "$n run(s) were still in flight locally:"
  sqlite3 "$ORCH/data/factory.db" "select '    ' || ticket_identifier || '  ' || task || '  since ' || created_at from runs where status in ('requested','running')"
  note "Start both again so they finish (remove the tickets' task labels first so nothing new starts), then stop them once more."
done
say "No runs in flight, and the local orchestrator is stopped. Don't start it again."
note "From now on, local work means tests only. Without FACTORY_POLL=on the laptop starts no runs anyway."
sqlite3 "$ORCH/data/factory.db" "PRAGMA wal_checkpoint(TRUNCATE);" >/dev/null
say "Folded the WAL into factory.db, so the one file holds everything."

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Create the Fly app and its volume"
fly auth whoami >/dev/null 2>&1 || { warn "flyctl isn't logged in: run 'fly auth login' and re-run."; exit 1; }
if fly apps list --json 2>/dev/null | grep -q "\"$APP\""; then
  say "App $APP already exists."
else
  confirm "Create the app $APP in your personal org?" || { warn "Every later stage needs the app: stopping here."; exit 1; }
  fly apps create "$APP" --org personal
fi
if fly volumes list -a "$APP" --json 2>/dev/null | grep -q '"factory_data"'; then
  say "Volume factory_data already exists."
else
  confirm "Create the 40 GB volume factory_data in iad?" || { warn "The deploy needs the volume: stopping here."; exit 1; }
  fly volumes create factory_data --size 40 --region iad -a "$APP" --yes
fi

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Set the secrets"
say "Every value in .env goes up as it is, plus DATA_DIR=/data. Nothing is printed."
note "FACTORY_POLL=on waits until the last stage, after the real factory.db is in place."
note "Names: $(grep -oE '^[A-Z_]+=' "$ENV_FILE" | grep -vE '^(INNGEST_DEV|FACTORY_POLL|DATA_DIR|PORT)=' | tr -d = | tr '\n' ' ')"
if confirm "Set these secrets on $APP?"; then
  { grep -E '^[A-Z_]+=' "$ENV_FILE" | grep -vE '^(INNGEST_DEV|FACTORY_POLL|DATA_DIR|PORT)='; echo "DATA_DIR=/data"; } \
    | fly secrets import -a "$APP" --stage
  fly secrets unset INNGEST_DEV -a "$APP" --stage >/dev/null 2>&1 || true
else
  SKIPPED+=("Fly secrets from .env (the machine can't run without them)")
fi

# ── 4 ────────────────────────────────────────────────────────────────────
stage "The first deploy"
say "Builds the image on Fly's builder and starts the one machine. It polls nothing yet."
if confirm "Deploy $(git rev-parse --short HEAD) now?"; then
  (cd "$ORCH" && fly deploy --remote-only --ha=false \
    --build-arg FACTORY_COMMIT="$(git rev-parse HEAD)" \
    --build-arg FACTORY_DEPLOYED_AT="$(date -u +%Y-%m-%dT%H:%M:%SZ)")
  curl --fail --silent https://$APP.fly.dev/health >/dev/null && say "Health check answers." || warn "https://$APP.fly.dev/health doesn't answer yet: check 'fly logs -a $APP'."
else
  SKIPPED+=("the first deploy (stage 5 needs a running machine)")
fi

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Copy factory.db up to the volume"
say "Uploads the laptop's factory.db, copies it over the empty one with SQLite's backup, then restarts."
note "Skip it to start from an empty database: no poll cursor (the first poll takes every labelled ticket),"
note "loop-cap counts start at zero, and implement's first update on a ticket treats every comment as new."
if confirm "Replace the machine's factory.db with the laptop's?"; then
  fly ssh console -a "$APP" -C "rm -f /data/incoming.db" >/dev/null 2>&1 || true
  fly ssh sftp put "$ORCH/data/factory.db" /data/incoming.db -a "$APP"
  fly ssh console -a "$APP" -C "node -e \"const D=require('/app/node_modules/better-sqlite3'); new D('/data/incoming.db',{readonly:true}).backup('/data/factory.db').then(()=>console.log('restored'))\""
  fly ssh console -a "$APP" -C "rm -f /data/incoming.db"
  fly apps restart "$APP"
  note "The restart runs the new migrations against the copied database."
else
  say "Skipped: the machine keeps its empty factory.db."
fi

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Inngest Cloud: sync the app"
open_url "https://app.inngest.com"
step "Switch to the Production environment (top left)."
step "Apps → Sync new app → paste https://$APP.fly.dev/api/inngest → Sync."
step "Check it lists 4 functions: poll-linear, run-ticket, run-cancelled, sweep-runs."
step "Manage → Event keys and Signing key: check INNGEST_EVENT_KEY and INNGEST_SIGNING_KEY in .env are Production's, not another environment's."
note "If they aren't, put Production's in .env and run: grep -E '^INNGEST_(EVENT|SIGNING)_KEY=' .env | fly secrets import -a $APP"
step "Turn on email alerts for failed function runs (look for alerts or notifications in the settings; the exact menu may differ)."
pause "Synced, keys checked and failure emails on?"

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Start the factory, and let GitHub deploy from now on"
if confirm "Set FACTORY_POLL=on, so the Fly machine starts runs?"; then
  fly secrets set FACTORY_POLL=on -a "$APP"
else
  SKIPPED+=("FACTORY_POLL=on (later: fly secrets set FACTORY_POLL=on -a $APP)")
fi
if confirm "Create a deploy token and set it as the GitHub secret FLY_API_TOKEN?"; then
  say "Creating an app-scoped deploy token for the GitHub Action (never shown)."
  set_secret FLY_API_TOKEN "$(fly tokens create deploy -a "$APP" -x 8760h)"
  note "The token lasts a year. Every push to main now checks, deploys and resyncs Inngest."
else
  SKIPPED+=("FLY_API_TOKEN (pushes to main fail their deploy until it's set)")
fi
say "The factory now:"
fly ssh console -a "$APP" -C "node /app/scripts/factory.ts status" || warn "factory status failed: see 'fly logs -a $APP'."
pause "Done?"

finish
}

run_wizard "$@"; exit
